-- github-tool.db (the mirror; a cache), schema v1.
--
-- A snapshot, not the source: the shape is created by the SCHEMA constant
-- in the code. This file is here so a later version can be diffed against
-- it, and so a fork can see exactly what a version was. Regenerated by
-- deploy/schema/dump.py; see docs/schema.md.

PRAGMA user_version = 1;

CREATE TABLE activity (
    id        TEXT PRIMARY KEY,      -- stable per item, so a re-poll is idempotent
    kind      TEXT NOT NULL,         -- commit | issue | pr | star | release
    actor     TEXT NOT NULL,
    repo      TEXT NOT NULL,
    ts_ms        INTEGER NOT NULL,
    title     TEXT NOT NULL DEFAULT '',
    url       TEXT NOT NULL DEFAULT '',
    state     TEXT NOT NULL DEFAULT ''
);

CREATE TABLE item (
    id         TEXT PRIMARY KEY,   -- owner/repo#number
    kind       TEXT NOT NULL,      -- issue | pr
    repo       TEXT NOT NULL,
    repo_owner TEXT NOT NULL,
    number     INTEGER NOT NULL,
    author     TEXT NOT NULL,
    title      TEXT NOT NULL DEFAULT '',
    url        TEXT NOT NULL DEFAULT '',
    draft      INTEGER NOT NULL DEFAULT 0,
    comments   INTEGER NOT NULL DEFAULT 0,
    created_at_ms INTEGER NOT NULL DEFAULT 0,
    updated_at_ms INTEGER NOT NULL DEFAULT 0,
    seen_at_ms    INTEGER NOT NULL
);

CREATE TABLE poll (
    scope   TEXT PRIMARY KEY,        -- what was polled, e.g. "user:toppk"
    etag    TEXT NOT NULL DEFAULT '',
    last_at_ms INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE repo (
    full_name  TEXT PRIMARY KEY,
    owner      TEXT NOT NULL,
    name       TEXT NOT NULL,
    private    INTEGER NOT NULL DEFAULT 0,
    fork       INTEGER NOT NULL DEFAULT 0,
    archived   INTEGER NOT NULL DEFAULT 0,
    stars      INTEGER NOT NULL DEFAULT 0,
    open_issues INTEGER NOT NULL DEFAULT 0,
    pushed_at_ms  INTEGER NOT NULL DEFAULT 0,
    description TEXT NOT NULL DEFAULT '',
    seen_at_ms    INTEGER NOT NULL
);

CREATE TABLE schema_history (
    version    INTEGER PRIMARY KEY,
    applied_ms INTEGER NOT NULL,
    by         TEXT NOT NULL DEFAULT ''
);

CREATE INDEX activity_actor ON activity (actor, ts_ms DESC);

CREATE INDEX activity_repo  ON activity (repo, ts_ms DESC);

CREATE INDEX activity_ts    ON activity (ts_ms DESC);

CREATE INDEX item_author ON item (author, updated_at_ms DESC);

CREATE INDEX item_owner  ON item (repo_owner, updated_at_ms DESC);
